import { test, expect, Page, Browser } from '@playwright/test';
import * as H from '../inventory/_places';
import { impersonate, backToAdmin } from '../warehouse-map/_helpers';
import { placeOrder, emptyCart } from '../orders/_qa-order';

test.use({ storageState: H.ADMIN });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const WORKER = 'עובד מחסן בדיקה';
const A = `QA-AUTO-picking-A-${TS}`;
const P = `QA-AUTO-picking-P-${TS}`;
const S = `QA-AUTO-picking-S-${TS}`;
const U = `QA-AUTO-picking-U-${TS}`;
const created = new Set<string>();
const used: H.Used = new Map();
type Order = { no: string; url: string; id: string };
const ids: Record<string, string> = {};
const state: { X?: H.Place; Y?: H.Place; Z?: H.Place; W?: H.Place; o1?: Order; o2?: Order } = {};

const PICK_ALL = 'ליקוט הכל';
const header = (page: Page) => page.getByRole('heading', { level: 1 }).locator('..');
const station = (page: Page, name: string) => page.getByRole('listitem').filter({ hasText: name });
const marked = (page: Page, name: string) => station(page, name).getByRole('button', { name: 'בטל סימון' });

async function openOrderById(page: Page, o: Order) {
  await page.goto(o.url);
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${o.no}` })).toBeVisible({ timeout: 30_000 });
}

async function approve(page: Page, no: string): Promise<Order> {
  await page.goto('/orders');
  await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
  await page.getByRole('button', { name: new RegExp(`^#${no} `) }).click();
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${no}` })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('button', { name: 'אישור הזמנה' }).click();
  const dlg = page.getByRole('dialog');
  await dlg.getByRole('textbox', { name: 'הערה (לא חובה)' }).fill(`QA-AUTO approve #6c161c ${TS}`);
  await dlg.getByRole('button', { name: 'אשר הזמנה' }).click();
  await expect(header(page)).toContainText('אושרה · ממתינה לליקוט', { timeout: 20_000 });
  const url = page.url();
  return { no, url, id: url.match(/orders\/([0-9a-f-]{36})/)![1] };
}

async function buyerOrder(browser: Browser, items: { id: string; name: string; qty: number }[], note: string) {
  const ctx = await browser.newContext({ storageState: H.auth('buyer'), locale: 'he-IL', baseURL: test.info().project.use.baseURL });
  try {
    return await placeOrder(await ctx.newPage(), items, note);
  } finally {
    await ctx.close();
  }
}

/** «החזרות» → «החזרה לספק» 1 шт. товара p из полки place (avail — сколько там сейчас). */
async function returnOneFromPlace(page: Page, p: string, place: H.Place, avail: number) {
  await H.openMap(page);
  await page.getByRole('button', { name: 'החזרות' }).click();
  await page.getByRole('menuitem', { name: /^החזרה לספק/ }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'החזרה לספק' })).toBeVisible();
  await dlg.getByRole('textbox', { name: 'חיפוש פריט' }).fill(p);
  const box = dlg.getByRole('checkbox', { name: new RegExp(`^${p} · \\S+ זמין ${avail} · מדף ${place.code}`) });
  await box.check();
  await box.locator('xpath=ancestor::label[1]/parent::*').getByRole('spinbutton', { name: `כמות ל${p}` }).fill('1');
  await dlg.getByRole('textbox', { name: 'לדוגמה: תנובה · תעודה 4471' }).fill(`QA-AUTO-picking-all-${TS}`);
  const resp = page.waitForResponse((r) => r.url().includes('/rpc/return_to_supplier') && r.request().method() === 'POST');
  await dlg.getByRole('button', { name: 'רישום ההחזרה' }).click();
  expect((await resp).status()).toBe(200);
  await expect(dlg).toHaveCount(0, { timeout: 15_000 });
}

/** Работник в отдельном окне: очередь → заказ → «התחלת ליקוט» → «רשימת ליקוט». Возвращает окно (закрыть после). */
async function openPickList(browser: Browser, o: Order) {
  const ctx = await browser.newContext({ storageState: H.ADMIN, locale: 'he-IL', viewport: { width: 1440, height: 900 }, baseURL: test.info().project.use.baseURL });
  const page = await ctx.newPage();
  await impersonate(page, WORKER);
  await page.goto(`/warehouse/picking?order=${o.id}`);
  await expect(page.getByRole('heading', { level: 2, name: `הזמנה #${o.no}` })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('button', { name: 'התחלת ליקוט', exact: true }).click();
  await expect(page.getByRole('heading', { level: 1, name: 'רשימת ליקוט' })).toBeVisible({ timeout: 30_000 });
  return { ctx, page };
}

/** Уборка: собрать хвост — «ליקוט הכל», остальное «חסר» со взятым количеством (или 0). */
async function pickAny(browser: Browser, o: Order) {
  const { ctx, page } = await openPickList(browser, o);
  try {
    const all = page.getByRole('button', { name: PICK_ALL });
    if (await all.count()) await all.click();
    for (const li of await page.getByRole('listitem').filter({ has: page.getByRole('button', { name: 'חסר', exact: true }) }).all()) {
      if (await li.getByRole('button', { name: 'בטל סימון' }).count()) continue;
      await li.getByRole('button', { name: 'חסר', exact: true }).click();
      const full = li.getByRole('button', { name: /^נלקטו כל/ });
      if (await full.count()) await full.click();
      else await li.getByRole('spinbutton', { name: 'כמה נלקטו בפועל?' }).fill('0');
      await li.getByRole('button', { name: 'אישור חוסר' }).click();
    }
    await expect(page.getByRole('button', { name: 'סיום ליקוט' })).toBeEnabled({ timeout: 15_000 });
    await page.getByRole('button', { name: 'סיום ליקוט' }).click();
    await expect(page.getByText(/הליקוט הושלם/)).toBeVisible({ timeout: 20_000 });
    await backToAdmin(page);
  } finally {
    await ctx.close();
  }
}

const shortDialog = (page: Page) => page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: 'ההזמנה לוקטה בחוסר' }) });

/** Довести заказ до «סופקה» (окно нехватки — подтвердить). */
async function deliver(page: Page) {
  for (const step of ['סמן כמוכנה למשלוח', 'סמן כיצאה למשלוח']) {
    const btn = page.getByRole('button', { name: step });
    if ((await btn.count()) && (await btn.isEnabled())) {
      await btn.click();
      await expect(btn).toHaveCount(0, { timeout: 20_000 });
    }
  }
  const done = page.getByRole('button', { name: 'סמן כסופקה' });
  if (!(await done.count())) return;
  await done.click();
  if (await shortDialog(page).isVisible().catch(() => false)) await shortDialog(page).getByRole('button', { name: 'סמן כסופקה' }).click();
  await expect(header(page)).toContainText(/סופקה?/, { timeout: 20_000 });
}

async function placeQty(page: Page, p: string, place: H.Place) {
  await H.openPlace(page, place);
  return H.qtyInPlacePanel(page, p);
}

test.describe('picking — «ליקוט הכל» ברשימת ליקוט (#6c161c)', () => {
  test.afterAll(async ({ browser }) => {
    test.setTimeout(600_000);
    const ctx = await browser.newContext({ storageState: H.ADMIN, locale: 'he-IL', viewport: { width: 1440, height: 900 }, baseURL: test.info().project.use.baseURL });
    const page = await ctx.newPage();
    try {
      for (const o of [state.o1, state.o2]) {
        if (!o?.id) continue;
        try {
          await openOrderById(page, o);
          const reject = page.getByRole('button', { name: 'דחייה' });
          if (await reject.count()) {
            await reject.click();
            const dlg = page.getByRole('dialog');
            await dlg.getByRole('textbox', { name: 'סיבת הדחייה *' }).fill('QA-AUTO cleanup #6c161c');
            await dlg.getByRole('button', { name: 'דחה הזמנה' }).click();
            await expect(header(page)).toContainText('נדחתה', { timeout: 20_000 });
            continue;
          }
          if (await header(page).getByText(/ממתינה לליקוט|בליקוט/).count()) {
            await pickAny(browser, o);
            await openOrderById(page, o);
          }
          await deliver(page);
        } catch (e) {
          test.info().annotations.push({ type: 'cleanup', description: `#${o.no}: ${(e as Error).message.split('\n')[0]}` });
        }
      }
    } finally {
      await ctx.close();
    }
    const bctx = await browser.newContext({ storageState: H.auth('buyer'), locale: 'he-IL', baseURL: test.info().project.use.baseURL });
    try { await emptyCart(await bctx.newPage()); } catch { /* корзина */ } finally { await bctx.close(); }
    await H.cleanup(browser, created, used);
  });

  test('«ליקוט הכל»: מסמן את כל התחנות שלא סומנו (כולל מוצר בשני מקומות), תחנה עם חוסר במדף נשארת — «חסר», הכפתור נעלם כשאין מה לסמן וחוזר אחרי «בטל סימון» #6c161c @desktop @data @orders', async ({ page, browser }) => {
    test.setTimeout(900_000);
    // --- подготовка: 4 свободные полки, товары A, P (2 места), S ---
    const [X, Y, Z, W] = await H.pickEmptyPlaces(page, 4, ['F', 'E', 'G']);
    Object.assign(state, { X, Y, Z, W });
    for (const [p, sku] of [[A, 'A'], [P, 'P'], [S, 'S']] as const) await H.createProduct(page, p, `QAPICK${sku}${TS}`, created, '0');
    H.track(used, A, X);
    H.track(used, P, Y, Z);
    H.track(used, S, W);
    await H.bindPlace(page, A, X);
    await H.bindPlace(page, P, Y);
    await H.bindPlace(page, P, Z, true);
    await H.bindPlace(page, S, W);
    await H.receive(page, A, 5, X.code);
    await H.receive(page, P, 4, Y.code);
    await H.receive(page, P, 5, Z.code);
    await H.receive(page, S, 2, W.code);
    for (const p of [A, P, S]) ids[p] = await H.productId(page, p);

    const no = await buyerOrder(browser, [
      { id: ids[A], name: A, qty: 2 },
      { id: ids[P], name: P, qty: 5 },
      { id: ids[S], name: S, qty: 2 },
    ], `QA-AUTO-picking-all-o1-${TS}`);
    state.o1 = { no, url: '', id: '' };
    state.o1 = await approve(page, no);
    await returnOneFromPlace(page, S, W, 2); // на полке W остаётся 1 из заказанных 2 → нехватка

    // --- ליקוט ---
    const { ctx, page: w } = await openPickList(browser, state.o1);
    try {
      const all = w.getByRole('button', { name: PICK_ALL, exact: true });
      const finish = w.getByRole('button', { name: 'סיום ליקוט' });
      await expect(w.getByText('0/3', { exact: true })).toBeVisible();
      await expect(station(w, P)).toContainText(Y.code);
      await expect(station(w, P)).toContainText(Z.code);
      // кнопка в нижней панели, над «סיום ליקוט»
      await expect(all).toBeVisible();
      await expect(finish).toBeDisabled();
      const ab = (await all.boundingBox())!;
      const fb = (await finish.boundingBox())!;
      expect(ab.y + ab.height, '«ליקוט הכל» над «סיום ליקוט»').toBeLessThanOrEqual(fb.y + 1);

      // одиночный «לוקט» остаётся (R6): A вручную
      await station(w, A).getByRole('button', { name: 'לוקט', exact: true }).click();
      await expect(w.getByText('1/3', { exact: true })).toBeVisible({ timeout: 15_000 });
      await expect(all).toBeVisible();

      // одно нажатие: P (2 места) → «לוקט»; S (на полке 1 из 2) — не отмечена
      await all.click();
      await expect(marked(w, P)).toBeVisible({ timeout: 20_000 });
      await expect(w.getByText('2/3', { exact: true })).toBeVisible({ timeout: 15_000 });
      await expect(marked(w, A)).toBeVisible();
      await expect(marked(w, S)).toHaveCount(0);
      await expect(station(w, S).getByRole('button', { name: 'חסר', exact: true })).toBeVisible();
      await expect(finish).toBeDisabled();
      await expect(w.getByText(/נותר/).filter({ hasText: /לפני סיום הליקוט/ })).toBeVisible();
      // отмечать кнопкой больше нечего (осталась только нехватка) → кнопки нет
      await expect(all).toHaveCount(0);

      // «בטל סימון» у A → кнопка снова есть → нажатие возвращает A в «לוקט»
      await marked(w, A).click();
      await expect(w.getByText('1/3', { exact: true })).toBeVisible({ timeout: 15_000 });
      await expect(all).toBeVisible();
      await all.click();
      await expect(marked(w, A)).toBeVisible({ timeout: 20_000 });
      await expect(w.getByText('2/3', { exact: true })).toBeVisible({ timeout: 15_000 });
      await expect(all).toHaveCount(0);
      await expect(marked(w, S)).toHaveCount(0);

      // S: «חסר» с фактическим количеством 1 из 2 → «סיום ליקוט» активна
      const st = station(w, S);
      await st.getByRole('button', { name: 'חסר', exact: true }).click();
      await expect(st.getByText(/נרשמו 1 מתוך 2/)).toBeVisible();
      await st.getByRole('spinbutton', { name: 'כמה נלקטו בפועל?' }).fill('1');
      await st.getByRole('button', { name: 'אישור חוסר' }).click();
      await expect(w.getByText('3/3', { exact: true })).toBeVisible({ timeout: 15_000 });
      await expect(all).toHaveCount(0);
      await expect(finish).toBeEnabled();
      await finish.click();
      await expect(w.getByText(/הליקוט הושלם/)).toBeVisible({ timeout: 20_000 });
      await backToAdmin(w);
    } finally {
      await ctx.close();
    }

    // --- остатки: списано один раз (повторная отметка A не списала дважды); P — по правилу 11.10 ---
    expect(await placeQty(page, A, X), 'A: 5 − 2').toBe(3);
    expect(await placeQty(page, P, Z), 'P: всё с места, где хватает (Z=5)').toBe(0);
    expect(await placeQty(page, P, Y), 'P: Y не тронут').toBe(4);
    await H.expectStock(page, A, 3);
    await H.expectStock(page, P, 4);
  });

  test('«ליקוט הכל» ברשימה נקייה: לחיצה אחת מסמנת הכל (כולל מוצר «ללא מיקום»), «סיום ליקוט» בלי סימון ידני → «לוקטה» #6c161c @desktop @data @orders', async ({ page, browser }) => {
    test.setTimeout(600_000);
    test.skip(!state.X || !ids[A], 'товар A не подготовлен');
    await H.createProduct(page, U, `QAPICKU${TS}`, created, '0');
    await H.receive(page, U, 1, null); // «ללא מיקום» (L-20261018-1: отмечается без проверки остатка)
    ids[U] = await H.productId(page, U);

    const no = await buyerOrder(browser, [
      { id: ids[A], name: A, qty: 1 },
      { id: ids[U], name: U, qty: 1 },
    ], `QA-AUTO-picking-all-o2-${TS}`);
    state.o2 = { no, url: '', id: '' };
    state.o2 = await approve(page, no);

    const { ctx, page: w } = await openPickList(browser, state.o2);
    try {
      const all = w.getByRole('button', { name: PICK_ALL, exact: true });
      const finish = w.getByRole('button', { name: 'סיום ליקוט' });
      await expect(w.getByText('0/2', { exact: true })).toBeVisible();
      await expect(finish).toBeDisabled();
      await all.click();
      await expect(w.getByText('2/2', { exact: true })).toBeVisible({ timeout: 20_000 });
      await expect(w.getByText('100% הושלמו')).toBeVisible();
      await expect(marked(w, A)).toBeVisible();
      await expect(marked(w, U)).toBeVisible();
      await expect(all).toHaveCount(0);
      await expect(w.getByText(/לפני סיום הליקוט/)).toHaveCount(0);
      await expect(finish).toBeEnabled();
      await finish.click();
      await expect(w.getByText('הליקוט הושלם — ההזמנה סומנה «לוקטה»')).toBeVisible({ timeout: 20_000 });
      await backToAdmin(w);
    } finally {
      await ctx.close();
    }

    await openOrderById(page, state.o2);
    await expect(page.getByText('כל הפריטים לוקטו במלואם.', { exact: true })).toBeVisible({ timeout: 30_000 });
    expect(await placeQty(page, A, state.X!), 'A: 3 − 1').toBe(2);
  });
});
